// 1. TRAER EL CARRITO
// ⚠️ IMPORTANTE: Cambia 'NOMBRE_DEL_NODO' por el nombre exacto del nodo 
// que leyó la hoja "datos user" (el que se ejecutó antes del Switch).
const rawCart = $('Get row(s) in sheet3').first().json.carrito || "";

// 2. TRAER EL MENÚ 
// (Esto lee la información del nodo que conectaste justo antes, el 'Get row(s) in sheet8')
const menuItems = $input.all().map(item => item.json);

// Validación rápida por si el carrito llega vacío
if (!rawCart.trim()) {
  return [{
    json: {
      total: 0,
      factura: "⚠️ No hay productos en tu carrito."
    }
  }];
}

// 3. PARSEAR EL CARRITO (Romper el string "1 2 | 3 1")
const pedidos = rawCart.split('|').map(itemStr => {
  const partes = itemStr.trim().split(/\s+/);
  return {
    id: partes[0],
    cantidad: parseInt(partes[1] || '1', 10) // Si no hay cantidad, asume 1
  };
});

let totalGeneral = 0;
let facturaText = "🧾 *RESUMEN Y TOTAL DE TU PEDIDO*\n\n";

// 4. CRUZAR DATOS Y CALCULAR EL TOTAL
pedidos.forEach(pedido => {
  // Busca el ID del producto en el menú que descargamos
  const producto = menuItems.find(p => String(p.id).trim() === String(pedido.id).trim());

  if (producto) {
    // Convierte el precio a número por si viene como texto desde Google Sheets
    const precio = parseFloat(String(producto.precio).replace(/[^0-9.-]+/g,"")) || 0;
    const subtotal = precio * pedido.cantidad;
    totalGeneral += subtotal;

    // Agrega la línea a la factura (formato moneda local)
    facturaText += `• ${producto.nombre} x${pedido.cantidad} → $${subtotal.toLocaleString('es-CO')}\n`;
  }
});

// 5. ARMAR EL MENSAJE FINAL
facturaText += `\n💳 *TOTAL A PAGAR:* $${totalGeneral.toLocaleString('es-CO')}\n`;
facturaText += `\n🛵 ¡Tu pedido ha sido registrado con éxito! Pronto saldrá hacia tu dirección.`;

// 6. ENVIAR LOS DATOS AL SIGUIENTE NODO
return [{
  json: {
    total: totalGeneral,
    factura: facturaText
  }
}];

