const inputItem = $input.item.json;

// Extraer el chat_id y el texto de forma segura (para mensajes o botones)
const chatId = inputItem.message?.chat?.id || inputItem.callback_query?.message?.chat?.id;
const text = inputItem.message?.text || inputItem.callback_query?.data || "";
const firstName = inputItem.message?.chat?.first_name || inputItem.callback_query?.from?.first_name || "Usuario";

// Lista de los chat_id de tus cocineros
const idsCocina = [8818238895]; 

let rol = "cliente";

// Si es un cocinero, usa el comando de login, o presiona un botón del panel de cocina
if (idsCocina.includes(chatId) || text === "/login 1234" || inputItem.callback_query) {
  rol = "cocina";
}

return {
  json: {
    chatId,
    text,
    firstName,
    rol
  }
};

const items = $input.all();

// Filtramos solo los que tengan estado "pendiente"
const pendientes = items.filter(item => {
  const row = item.json || {};
  const estado = String(row.estado || "").trim().toLowerCase();
  return estado === "pendiente";
});

if (pendientes.length === 0) {
  return [{ json: { mensajeCocina: "📭 No hay pedidos pendientes en este momento." } }];
}

let textoLista = "📋 *LISTA DE PEDIDOS PENDIENTES*:\n\n";

pendientes.forEach((item, index) => {
  const row = item.json || {};
  const idPedido = row.id || row.row_number || (index + 1);

  textoLista += `🆔 *ID del Pedido:* ${idPedido}\n`;
  textoLista += `👤 *Cliente:* ${row.nombre || 'Sin nombre'}\n`;
  textoLista += `🛒 *Producto/Detalle:* ${row.direccion || row.producto || 'N/A'}\n`;
  textoLista += `💰 *Total:* $${row.total || '0'}\n`;
  textoLista += `-----------------------------------\n`;
});

return [{ json: { mensajeCocina: textoLista } }];

// Obtener el número que digitó el cocinero
const numeroDigitado = $('Switch5').first().json.text;

// Filtrar para quedarse únicamente con el ítem cuyo row_number coincida exactamente
return $input.all().filter(item => item.json.row_number == numeroDigitado);
